let state;
function fresh(){return {turn:0,phase:'waiting',message:'관리자가 게임을 시작하면 1월이 시작됩니다.',prices:[...initial],delisted:[],players:{},trades:[],news:newsSeed.map(n=>({...n,claimedBy:null})),quizUsed:{},eventCounts:{},eventHistory:[],eventDeck:{},rngTurn:0};}
function load(){try{if(fs.existsSync(SAVE)){const d=JSON.parse(fs.readFileSync(SAVE,'utf8'));if(d&&d.players&&d.prices) return d;}}catch(e){console.error('save load failed',e.message)}return fresh()}
state=load();
function save(){try{const dir=path.dirname(SAVE);if(dir&&dir!=='.'&&!fs.existsSync(dir))fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(SAVE,JSON.stringify(state));}catch(e){console.error('save failed',e.message)}}
function cashValue(p){return Math.round(p.cash+ p.holdings.reduce((s,q,i)=>s+q*(state.delisted.includes(i)?0:state.prices[i]),0))}
function sorted(){return Object.values(state.players).map(p=>({...p,total:cashValue(p),stockValue:p.holdings.reduce((s,q,i)=>s+q*(state.delisted.includes(i)?0:state.prices[i]),0)})).sort((a,b)=>b.total-a.total||a.nickname.localeCompare(b.nickname,'ko')).map((p,i)=>({...p,rank:i+1}))}
function online(p){return !!(p.socketId&&io.sockets.sockets.get(p.socketId))}
function details(p){return p.holdings.map((qty,i)=>({company:companies[i],qty,price:state.delisted.includes(i)?0:state.prices[i],value:qty*(state.delisted.includes(i)?0:state.prices[i])})).filter(x=>x.qty>0)}
function pubPlayer(p,rank){return {id:p.id,nickname:p.nickname,cash:p.cash,total:cashValue(p),rank,holdings:p.holdings,holdingsDetail:details(p),history:p.history,online:online(p),stockValue:details(p).reduce((s,h)=>s+h.value,0)}}
function leaderboard(){return sorted().map(p=>({id:p.id,nickname:p.nickname,total:p.total,rank:p.rank,online:online(p)}))}
function quizFor(p){if(!p.quizId){let available=quiz.filter(q=>!p.quizSeen.includes(q.id));if(!available.length){p.quizSeen=[];available=quiz.slice()}const q=available[Math.floor(Math.random()*available.length)];p.quizId=q.id;}const q=quiz.find(q=>q.id===p.quizId);return q?{id:q.id,category:q.category,question:q.question,kind:q.kind,options:q.options,answered:!!p.quizAnswered,feedback:p.quizFeedback||''}:null}
function playerNews(p){return state.news.filter(n=>n.claimedBy===p.id).map(n=>({id:n.id,month:n.month,company:n.company,text:n.text,truth:n.truth,impact:n.impact}))}
function privateState(p){const sortedP=sorted(),self=sortedP.find(x=>x.id===p.id);return {turn:state.turn,month:state.turn?months[state.turn-1]:'시작 전',phase:state.phase,message:state.message,companies,prices:state.prices.map((v,i)=>state.delisted.includes(i)?0:v),delisted:state.delisted,self:self?{...pubPlayer(p,self.rank),quiz:quizFor(p),news:playerNews(p),event:(state.eventDeck[p.id]&&state.eventDeck[p.id].type==='card'?{type:'card',resolved:!!state.eventDeck[p.id].resolved,result:state.eventDeck[p.id].result}:state.eventDeck[p.id])||null}:null,leaderboard:leaderboard(),transactions:state.trades.filter(t=>t.playerId===p.id).slice(-80),newsClaimed:state.news.filter(n=>n.claimedBy).length};}
function adminState(){return {turn:state.turn,phase:state.phase,players:sorted().map(p=>pubPlayer(state.players[p.id],p.rank)),transactions:state.trades.slice(-250).reverse(),allNews:state.news.map(n=>({...n,claimedBy:n.claimedBy?state.players[n.claimedBy]?.nickname||'플레이어':'미배포'})),companies,prices:state.prices,delisted:state.delisted,message:state.message,eventHistory:state.eventHistory.slice(-100),eventCounts:state.eventCounts};}
function broadcast(){for(const p of Object.values(state.players)){const sock=p.socketId&&io.sockets.sockets.get(p.socketId);if(sock)sock.emit('state',privateState(p));}io.to('admins').emit('adminState',adminState());save();}
function addTrade(p,side,i,qty,price){state.trades.push({id:Date.now()+Math.random(),playerId:p.id,nickname:p.nickname,month:months[Math.max(0,state.turn-1)]||'시작 전',action:side==='buy'?'매수':'매도',company:companies[i],qty,total:qty*price,price,at:new Date().toISOString()});}
function nextTurn(){if(state.turn>=12){state.phase='ended';state.message='12월 종료! 최종 순위가 확정되었습니다.';broadcast();return;}
// 이전 턴에 구걸 이벤트에서 약속된 보답 지급
for(const p of Object.values(state.players)){const prior=state.eventDeck[p.id];if(prior&&prior.type==='homeless'&&prior.reward&&!prior.rewardPaid){p.cash+=10000000;prior.rewardPaid=true;state.eventHistory.push({player:p.nickname,type:'구걸 보답',result:'약속한 1,000만원 지급',month:months[Math.max(0,state.turn-1)]});}}
state.turn++;state.phase='running';state.message=months[state.turn-1]+' 시작 — 주가와 이벤트가 갱신되었습니다.';const old=[...state.prices];state.prices=state.prices.map((p,i)=>{if(state.delisted.includes(i))return 0;let pct=(Math.random()<0.5?-1:1)*(10+Math.floor(Math.random()*90));const seasonal={11:{12:14,4:12,10:10},2:{9:12,0:8},6:{2:8,7:8},12:{10:14,11:8},9:{4:10,9:8}};const bonus=seasonal[state.turn]?.[i]||0;pct=Math.max(-99,Math.min(99,pct+bonus));return Math.max(100,Math.round(p*(1+pct/100)));});
if(Math.random()<0.035){const candidates=state.prices.map((p,i)=>i).filter(i=>!state.delisted.includes(i));if(candidates.length>3){const i=candidates[Math.floor(Math.random()*candidates.length)];state.delisted.push(i);state.prices[i]=0;state.message+=' '+companies[i]+' 상장폐지!';}}
for(const p of Object.values(state.players)){p.history.push({month:months[state.turn-1],value:cashValue(p)});p.quizAnswered=false;p.quizFeedback='';p.quizId=null;state.eventDeck[p.id]=null;}
assignEvents();broadcast();}
function assignEvents(){const ps=Object.values(state.players);if(!ps.length)return;const shuffled=[...ps].sort(()=>Math.random()-.5);let eligible=shuffled.filter(p=>(state.eventCounts[p.id]||0)<3);let minNeeded=ps.filter(p=>(state.eventCounts[p.id]||0)===0);let homelessN=Math.min(3,Math.max(1,minNeeded.length));let selected=[];for(const p of minNeeded.slice(0,homelessN))selected.push(p);for(const p of eligible){if(selected.length>=homelessN)break;if(!selected.includes(p))selected.push(p)}selected.forEach(p=>{state.eventDeck[p.id]={type:'homeless',resolved:false,homelessType:Math.random()<.5?'잘생긴 노숙자':'못생긴 노숙자'};state.eventCounts[p.id]=(state.eventCounts[p.id]||0)+1;});
const rank=sorted();const gamblers=rank.filter(p=>p.rank>=11&&p.rank<=19);if(gamblers.length){const p=gamblers[Math.floor(Math.random()*gamblers.length)];if(!state.eventDeck[p.id])state.eventDeck[p.id]={type:'bet',resolved:false};}
if(state.turn%2===0){const p=shuffled.find(p=>!state.eventDeck[p.id])||shuffled[0];if(p)state.eventDeck[p.id]={type:'card',resolved:false,order:[0,1,2].sort(()=>Math.random()-.5)};}}
function homelessChoice(p,choice){const ev=state.eventDeck[p.id];if(!ev||ev.type!=='homeless'||ev.resolved)return;const total=cashValue(p);let msg='';if(choice==='give'){if(Math.random()<.5){ev.reward=true;msg='노숙자가 보답을 약속했습니다. 다음 턴에 1,000만원을 받습니다.';}else{stealHalf(p);msg='안타깝게도 재산의 절반을 잃었습니다.';}}else if(Math.random()<.7){stealHalf(p);msg='재산의 절반을 몰수당했습니다.';}else msg='다행히 아무 일도 일어나지 않았습니다.';ev.resolved=true;ev.result=msg;state.eventHistory.push({player:p.nickname,type:'구걸',result:msg,month:months[state.turn-1]});broadcast();}
function stealHalf(p){let half=Math.floor(cashValue(p)/2);let fromCash=Math.min(p.cash,half);p.cash-=fromCash;let remain=half-fromCash;while(remain>0){let owned=p.holdings.map((q,i)=>({q,i})).filter(x=>x.q>0&&!state.delisted.includes(x.i));if(!owned.length)break;let item=owned[Math.floor(Math.random()*owned.length)],price=state.prices[item.i];if(price<=0)break;let n=Math.min(item.q,Math.max(1,Math.ceil(remain/price)));p.holdings[item.i]-=n;remain-=n*price;}}
function action(socket,payload){if(!socket.data.admin)return;const a=payload;if(a==='start'){if(state.phase==='waiting')nextTurn();else broadcast()}else if(a==='next'){if(state.phase==='paused')state.phase='running';nextTurn()}else if(a==='pause'){state.phase=state.phase==='paused'?'running':'paused';state.message=state.phase==='paused'?'게임이 일시정지되었습니다.':'게임이 재개되었습니다.';broadcast()}else if(a==='reset'){state=fresh();broadcast();}}
io.on('connection',socket=>{
 socket.on('join',({nickname}={})=>{nickname=String(nickname||'').trim().slice(0,18);if(!nickname)return socket.emit('errorMsg','닉네임을 입력해주세요.');let p=Object.values(state.players).find(x=>x.nickname.toLowerCase()===nickname.toLowerCase());if(p&&p.socketId&&io.sockets.sockets.get(p.socketId))return socket.emit('errorMsg','이미 사용 중인 닉네임입니다.');if(!p){if(Object.keys(state.players).length>=25)return socket.emit('errorMsg','참가 인원 25명이 가득 찼습니다.');const id='P'+Math.random().toString(36).slice(2,10);p=state.players[id]={id,nickname,cash:10000000,holdings:companies.map(()=>0),history:[{month:'시작',value:10000000}],quizSeen:[],quizId:null,quizAnswered:false,quizFeedback:'',socketId:null};}p.socketId=socket.id;socket.data.playerId=p.id;socket.emit('joined',{id:p.id,nickname:p.nickname});socket.emit('state',privateState(p));broadcast();});
 socket.on('adminLogin',pin=>{if(String(pin)!==PIN)return socket.emit('errorMsg','암호가 올바르지 않습니다.');socket.data.admin=true;socket.join('admins');socket.emit('adminOk');socket.emit('adminState',adminState());});
 socket.on('adminAction',a=>action(socket,a));
 socket.on('adminGetQuizBank',()=>{if(socket.data.admin)socket.emit('adminQuizBank',quiz.map(q=>({id:q.id,category:q.category,question:q.question,answer:q.answer,kind:q.kind,options:q.options})));});
 socket.on('trade',({side,index,qty}={})=>{const p=state.players[socket.data.playerId];if(!p||state.phase!=='running')return socket.emit('errorMsg','게임 진행 중에만 거래할 수 있습니다.');index=Number(index);qty=Number(qty);if(!Number.isInteger(index)||index<0||index>=companies.length||!Number.isInteger(qty)||qty<1||qty>100000)return socket.emit('tradeResult',{error:'주식 수는 1 이상의 정수여야 합니다.'});if(state.delisted.includes(index)||state.prices[index]<=0)return socket.emit('tradeResult',{error:'상장폐지된 종목은 거래할 수 없습니다.'});const price=state.prices[index];if(side==='buy'){const cost=price*qty;if(!Number.isSafeInteger(cost)||cost>p.cash)return socket.emit('tradeResult',{error:'현금이 부족합니다.'});p.cash-=cost;p.holdings[index]+=qty;}else if(side==='sell'){if(p.holdings[index]<qty)return socket.emit('tradeResult',{error:'보유 주식 수가 부족합니다.'});p.holdings[index]-=qty;p.cash+=price*qty;}else return;addTrade(p,side,index,qty,price);broadcast();socket.emit('tradeResult',{ok:true});});
 socket.on('claimNews',()=>{const p=state.players[socket.data.playerId];if(!p||state.phase!=='running')return socket.emit('errorMsg','게임 진행 중에만 힌트를 받을 수 있습니다.');const existing=state.news.find(n=>n.claimedBy===p.id&&n.turn===state.turn);if(existing)return socket.emit('privateNews',existing);const n=state.news.find(n=>n.turn===state.turn&&!n.claimedBy);if(!n)return socket.emit('errorMsg','이번 턴에 배포할 힌트가 모두 소진되었습니다.');n.claimedBy=p.id;socket.emit('privateNews',n);broadcast();});
 socket.on('answerQuiz',({id,answer}={})=>{const p=state.players[socket.data.playerId];if(!p||p.quizAnswered)return;const q=quiz.find(q=>q.id===p.quizId);if(!q)return;const correct=String(answer)===String(q.answer);p.quizAnswered=true;p.quizSeen.push(q.id);p.quizFeedback=correct?'정답입니다!':'아쉽지만 오답입니다. 정답: '+q.answer; if(correct)p.cash+=100000;socket.emit('quizResult',{correct,answer:q.answer,feedback:p.quizFeedback,reward:correct?100000:0});broadcast();});
 socket.on('homelessChoice',choice=>{const p=state.players[socket.data.playerId];if(p)homelessChoice(p,choice);});
 socket.on('betChoice',yes=>{const p=state.players[socket.data.playerId],ev=p&&state.eventDeck[p.id];if(!p||!ev||ev.type!=='bet'||ev.resolved)return;let msg;if(!yes)msg='이번에는 도전하지 않았습니다.';else if(Math.random()<.1){p.cash+=10000000;msg='성공! 1,000만원을 받았습니다.';}else{p.cash=Math.max(0,p.cash-5000000);msg='실패! 현금에서 최대 500만원이 차감되었습니다.';}ev.resolved=true;ev.result=msg;state.eventHistory.push({player:p.nickname,type:'인생은 한 방',result:msg,month:months[state.turn-1]});broadcast();socket.emit('eventResult',msg);});
 socket.on('cardChoice',index=>{const p=state.players[socket.data.playerId],ev=p&&state.eventDeck[p.id];if(!p||!ev||ev.type!=='card'||ev.resolved)return;const choice=ev.order[Number(index)];let msg;if(choice===0)msg='아무 일도 일어나지 않았습니다.';else if(choice===1){p.cash+=3000000;msg='300만원을 받았습니다!';}else{const others=Object.values(state.players).filter(q=>q.id!==p.id);if(!others.length)msg='교환할 상대가 없어 아무 일도 일어나지 않았습니다.';else{const target=others[Math.floor(Math.random()*others.length)];const h=p.holdings;p.holdings=target.holdings;target.holdings=h;const cash=p.cash;p.cash=target.cash;target.cash=cash;msg=target.nickname+'와 자산이 교환되었습니다.';}}ev.resolved=true;ev.result=msg;state.eventHistory.push({player:p.nickname,type:'랜덤 카드',result:msg,month:months[state.turn-1]});broadcast();socket.emit('eventResult',msg);});
 socket.on('adminSendNews',({playerId,newsId}={})=>{if(!socket.data.admin)return;const p=state.players[playerId],n=state.news.find(x=>x.id===newsId);if(!p||!n||n.claimedBy)return socket.emit('errorMsg','플레이어 또는 미배포 뉴스를 확인해주세요.');n.claimedBy=p.id;const ps=p.socketId&&io.sockets.sockets.get(p.socketId);if(ps)ps.emit('privateNews',n);broadcast();});
 socket.on('disconnect',()=>{const p=state.players[socket.data.playerId];if(p&&p.socketId===socket.id){p.socketId=null;broadcast();}});
});
server.listen(PORT,'0.0.0.0',()=>console.log('BLUE MARKET running on '+PORT));
